  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  parsed_json?: any;
 48→}
 49→
 50→export interface ExistingResume {
 51→  id: string;
 52→  filename: string;
 53→  file_path: string | null;
 54→  candidate_name: string | null;
 55→  created_at: string;
 56→}
 57→
 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      console.error("Failed to load past jobs:", err);
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      // Deduplicate by resume_id — keep highest scoring result per resume
158→      const deduped = new Map<string, Result>();
159→      for (const r of allMerged) {
160→        const existing = deduped.get(r.resume_id);
161→        if (!existing || r.overall_score > existing.overall_score) {
162→          deduped.set(r.resume_id, r);
163→        }
164→      }
165→      const merged = Array.from(deduped.values());
166→      merged.sort((a, b) => b.overall_score - a.overall_score);
167→      setResults(merged);
168→    } catch (err) {
169→      console.error("Failed to load job data:", err);
170→      toast.error("Failed to load job data");
171→    }
172→  };
173→
174→  const handleNewJob = () => {
175→    setSelectedJobId(null);
176→    setResults([]);
177→    setExistingResumes([]);
178→  };
179→
180→  const handleJobCreated = (job: PastJob) => {
181→    setPastJobs((prev) => [job, ...prev]);
182→    setSelectedJobId(job.id);
183→    loadJobData(job.id);
184→  };
185→
186→  const handleRenameJob = (jobId: string, newTitle: string) => {
187→    setPastJobs((prev) =>
188→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
189→    );
190→  };
191→
192→  const handleDeleteJob = async (jobId: string) => {
193→    try {
194→      await supabase.from("resumes").delete().eq("job_id", jobId);
195→      await supabase.from("jobs").delete().eq("id", jobId);
196→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
197→      if (selectedJobId === jobId) handleNewJob();
198→      toast.success("Job deleted");
199→    } catch {
200→      toast.error("Failed to delete job");
201→    }
202→  };
203→
204→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
205→    setPastJobs((prev) =>
206→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
207→    );
208→  };
209→
210→  const requireAuth = useCallback(() => {
211→    if (!user) { setAuthOpen(true); return true; }
212→    return false;
213→  }, [user]);
214→
215→  return (
216→    <SidebarProvider className="h-svh overflow-hidden">
217→      <JobSidebar
218→        pastJobs={pastJobs}
219→        selectedJobId={selectedJobId}
220→        loadingPastJobs={loadingPastJobs}
221→        onSelectJob={loadJobData}
222→        onNewJob={handleNewJob}
223→        onRenameJob={handleRenameJob}
224→        onDeleteJob={handleDeleteJob}
225→        onAuthRequired={() => setAuthOpen(true)}
226→        isAuthenticated={!!user}
227→      />
228→
229→      <SidebarInset className="h-svh overflow-y-auto">
230→        <AppHeader />
231→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
232→          <SidebarTrigger />
233→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
234→        </div>
235→        <JobDetailView
236→          selectedJobId={selectedJobId}
237→          selectedJob={selectedJob}
238→          results={results}
239→          setResults={setResults}
240→          existingResumes={existingResumes}
241→          setExistingResumes={setExistingResumes}
242→          onJobCreated={handleJobCreated}
243→          onAuthRequired={() => setAuthOpen(true)}
244→          isAuthenticated={!!user}
245→          onJobUpdated={handleJobUpdated}
246→        />
247→      </SidebarInset>
248→
249→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
250→    </SidebarProvider>
251→  );
252→};
253→
254→export default Index;
255→

 1→import { Card, CardContent } from "@/components/ui/card";
 2→import { Target, ShieldCheck, BarChart3, TrendingUp } from "lucide-react";
 3→import type { Result } from "@/pages/Index";
 4→
 5→interface ScoreSummaryCardsProps {
 6→  results: Result[];
 7→}
 8→
 9→const ScoreSummaryCards = ({ results }: ScoreSummaryCardsProps) => {
10→  const scored = results.filter((r) => !r.pending);
11→  if (scored.length === 0) return null;
12→
13→  const avg = (fn: (r: Result) => number) =>
14→    Math.round(scored.reduce((sum, r) => sum + fn(r), 0) / scored.length);
15→
16→  // Compute avg category score from category_scores_json (the actual dynamic scores)
17→  const avgCategoryScore = (r: Result): number => {
18→    if (!r.category_scores_json || typeof r.category_scores_json !== "object") return 0;
19→    const entries = Object.values(r.category_scores_json as Record<string, { score: number }>);
20→    if (entries.length === 0) return 0;
21→    return entries.reduce((sum, e) => sum + (e.score ?? 0), 0) / entries.length;
22→  };
23→
24→  // Compute JD match % from matched vs total must-haves
25→  const jdMatchPercent = (r: Result): number => {
26→    const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
27→    const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
28→    const total = matched + missing;
29→    if (total === 0) return 0;
30→    return Math.round((matched / total) * 100);
31→  };
32→
33→  const cards = [
34→    {
35→      label: "Overall Match",
36→      value: avg((r) => r.overall_score),
37→      icon: Target,
38→      color: "bg-score-overall",
39→      textColor: "text-score-overall",
40→      bgLight: "bg-score-overall/10",
41→    },
42→    {
43→      label: "Avg Skill Score",
44→      value: avg(avgCategoryScore),
45→      icon: BarChart3,
46→      color: "bg-score-skills",
47→      textColor: "text-score-skills",
48→      bgLight: "bg-score-skills/10",
49→    },
50→    {
51→      label: "Confidence",
52→      value: avg((r) => r.confidence ?? 0),
53→      icon: TrendingUp,
54→      color: "bg-score-education",
55→      textColor: "text-score-education",
56→      bgLight: "bg-score-education/10",
57→    },
58→    {
59→      label: "JD Alignment",
60→      value: avg(jdMatchPercent),
61→      icon: ShieldCheck,
62→      color: "bg-score-jd",
63→      textColor: "text-score-jd",
64→      bgLight: "bg-score-jd/10",
65→    },
66→  ];
67→
68→  return (
69→    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
70→      {cards.map((card) => (
71→        <Card key={card.label} className="overflow-hidden">
72→          <CardContent className="p-4">
73→            <div className="flex items-center gap-2 mb-3">
74→              <div className={`w-8 h-8 rounded-lg ${card.bgLight} flex items-center justify-center`}>
75→                <card.icon className={`h-4 w-4 ${card.textColor}`} />
76→              </div>
77→              <span className="text-xs font-medium text-muted-foreground">{card.label}</span>
78→            </div>
79→            <div className="flex items-end gap-1 mb-2">
80→              <span className={`text-2xl font-bold tabular-nums ${card.textColor}`}>
81→                {card.value}
82→              </span>
83→              <span className="text-sm text-muted-foreground mb-0.5">%</span>
84→            </div>
85→            <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
86→              <div
87→                className={`h-full rounded-full transition-all duration-500 ${card.color}`}
88→                style={{ width: `${Math.min(card.value, 100)}%` }}
89→              />
90→            </div>
91→          </CardContent>
92→        </Card>
93→      ))}
94→    </div>
95→  );
96→};
97→
98→export default ScoreSummaryCards;
99→

  1→import { useState, useMemo, useRef, useEffect } from "react";
  2→import { cn } from "@/lib/utils";
  3→import { Plus, Clock, Loader2, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText } from "lucide-react";
  4→import { format } from "date-fns";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { SidebarInput } from "@/components/ui/sidebar";
  8→import { supabase } from "@/integrations/supabase/client";
  9→import { toast } from "sonner";
 10→import {
 11→  DropdownMenu,
 12→  DropdownMenuContent,
 13→  DropdownMenuItem,
 14→  DropdownMenuTrigger,
 15→} from "@/components/ui/dropdown-menu";
 16→import {
 17→  AlertDialog,
 18→  AlertDialogAction,
 19→  AlertDialogCancel,
 20→  AlertDialogContent,
 21→  AlertDialogDescription,
 22→  AlertDialogFooter,
 23→  AlertDialogHeader,
 24→  AlertDialogTitle,
 25→} from "@/components/ui/alert-dialog";
 26→import {
 27→  Sidebar,
 28→  SidebarContent,
 29→  SidebarHeader,
 30→  SidebarGroup,
 31→  SidebarGroupLabel,
 32→  SidebarGroupContent,
 33→  SidebarMenu,
 34→  SidebarMenuItem,
 35→  SidebarMenuButton,
 36→} from "@/components/ui/sidebar";
 37→
 38→interface PastJob {
 39→  id: string;
 40→  title: string | null;
 41→  job_description: string;
 42→  status: string;
 43→  created_at: string;
 44→  resume_count: number;
 45→}
 46→
 47→interface JobSidebarProps {
 48→  pastJobs: PastJob[];
 49→  selectedJobId: string | null;
 50→  loadingPastJobs: boolean;
 51→  onSelectJob: (jobId: string) => void;
 52→  onNewJob: () => void;
 53→  onRenameJob: (jobId: string, newTitle: string) => void;
 54→  onDeleteJob: (jobId: string) => void;
 55→  onAuthRequired?: () => void;
 56→  isAuthenticated?: boolean;
 57→}
 58→
 59→function getDisplayTitle(job: PastJob): string {
 60→  if (job.title) return job.title;
 61→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 62→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 63→}
 64→
 65→const JobSidebar = ({ pastJobs, selectedJobId, loadingPastJobs, onSelectJob, onNewJob, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
 66→  const [search, setSearch] = useState("");
 67→  const [editingId, setEditingId] = useState<string | null>(null);
 68→  const [editValue, setEditValue] = useState("");
 69→  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
 70→  const editInputRef = useRef<HTMLInputElement>(null);
 71→
 72→  const filteredJobs = useMemo(() => {
 73→    if (!search.trim()) return pastJobs;
 74→    const q = search.toLowerCase();
 75→    return pastJobs.filter(
 76→      (job) =>
 77→        getDisplayTitle(job).toLowerCase().includes(q) ||
 78→        job.job_description.toLowerCase().includes(q)
 79→    );
 80→  }, [pastJobs, search]);
 81→
 82→  useEffect(() => {
 83→    if (editingId && editInputRef.current) {
 84→      editInputRef.current.focus();
 85→      editInputRef.current.select();
 86→    }
 87→  }, [editingId]);
 88→
 89→  const startEditing = (job: PastJob) => {
 90→    setEditingId(job.id);
 91→    setEditValue(getDisplayTitle(job));
 92→  };
 93→
 94→  const saveRename = async () => {
 95→    if (!editingId || !editValue.trim()) {
 96→      setEditingId(null);
 97→      return;
 98→    }
 99→    try {
100→      const { error } = await supabase
101→        .from("jobs")
102→        .update({ title: editValue.trim() } as any)
103→        .eq("id", editingId);
104→      if (error) throw error;
105→      onRenameJob(editingId, editValue.trim());
106→      toast.success("Job renamed");
107→    } catch {
108→      toast.error("Failed to rename job");
109→    }
110→    setEditingId(null);
111→  };
112→
113→  const cancelEditing = () => setEditingId(null);
114→
115→  const confirmDelete = () => {
116→    if (deleteJobId) {
117→      onDeleteJob(deleteJobId);
118→      setDeleteJobId(null);
119→    }
120→  };
121→
122→  return (
123→    <>
124→      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
125→        <SidebarHeader className="p-4 space-y-3">
126→          <Button onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }} className="w-full gap-2" size="sm">
127→            <Plus className="h-4 w-4" />
128→            New Job
129→          </Button>
130→          <div className="relative">
131→            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
132→            <SidebarInput
133→              placeholder="Search jobs…"
134→              value={search}
135→              onChange={(e) => setSearch(e.target.value)}
136→              className="pl-8"
137→            />
138→          </div>
139→        </SidebarHeader>
140→
141→        <SidebarContent>
142→          <SidebarGroup>
143→            <SidebarGroupLabel className="px-4 flex items-center gap-2">
144→              <Briefcase className="h-4 w-4" />
145→              <span>Job History</span>
146→              {search && <span className="ml-auto text-[10px]">({filteredJobs.length})</span>}
147→            </SidebarGroupLabel>
148→            <SidebarGroupContent>
149→              {!isAuthenticated ? (
150→                <div className="px-3 py-3">
151→                  <button
152→                    onClick={() => onAuthRequired?.()}
153→                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
154→                  >
155→                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
156→                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
157→                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
158→                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
159→                      Sign in to get started →
160→                    </span>
161→                  </button>
162→                </div>
163→              ) : loadingPastJobs ? (
164→                <div className="flex items-center justify-center py-8">
165→                  <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
166→                </div>
167→              ) : filteredJobs.length === 0 ? (
168→                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
169→                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
170→                </p>
171→              ) : (
172→                <SidebarMenu className="space-y-1.5 px-2">
173→                  {filteredJobs.map((job) => (
174→                    <SidebarMenuItem key={job.id}>
175→                      {editingId === job.id ? (
176→                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
177→                          <Input
178→                            ref={editInputRef}
179→                            value={editValue}
180→                            onChange={(e) => setEditValue(e.target.value)}
181→                            onKeyDown={(e) => {
182→                              if (e.key === "Enter") saveRename();
183→                              if (e.key === "Escape") cancelEditing();
184→                            }}
185→                            onBlur={saveRename}
186→                            className="h-7 text-sm"
187→                          />
188→                        </div>
189→                      ) : (
190→                        <SidebarMenuButton
191→                          isActive={selectedJobId === job.id}
192→                          onClick={() => onSelectJob(job.id)}
193→                          className={cn(
194→                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
195→                            "rounded-lg border bg-card shadow-sm",
196→                            "hover:shadow-md hover:border-border transition-all",
197→                            selectedJobId === job.id
198→                              ? "border-l-2 border-l-primary bg-sidebar-accent shadow-md"
199→                              : "border-border/60"
200→                          )}
201→                        >
202→                          <div className="flex items-center gap-1 w-full">
203→                            <span className="text-sm leading-snug line-clamp-2 flex-1">
204→                              {getDisplayTitle(job)}
205→                            </span>
206→                            <DropdownMenu>
207→                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
208→                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
209→                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
210→                                </button>
211→                              </DropdownMenuTrigger>
212→                              <DropdownMenuContent align="end" className="w-36">
213→                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
214→                                  <Pencil className="h-3.5 w-3.5 mr-2" />
215→                                  Rename
216→                                </DropdownMenuItem>
217→                                <DropdownMenuItem
218→                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
219→                                  className="text-destructive focus:text-destructive"
220→                                >
221→                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
222→                                  Delete
223→                                </DropdownMenuItem>
224→                              </DropdownMenuContent>
