 97→  const { data: stages } = useStages(selectedJobId);
 98→  const updateStageMutation = useUpdateStage();
 99→  const stageSummary = useStageSummary(selectedJobId);
100→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
101→
102→  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
103→    if (!selectedJobId) return;
104→    const current = stageMap.get(resumeId);
105→    updateStageMutation.mutate({
106→      resumeId,
107→      jobId: selectedJobId,
108→      newStage,
109→      currentStage: current?.stage,
110→    });
111→  };
