481→              .in("resume_id", allResumeIds);
482→
483→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
484→            const allMerged: Result[] = (resultData ?? []).map((r: any) => {
485→              const resume = resumeMap.get(r.resume_id);
486→              const parsed = resume?.parsed_json as any;
487→              return {
488→                ...r,
489→                overall_score: r.overall_score ?? 0,
